classified=[]
for source,owner,decision in zip(scope['sources'],scope['owners'],prescriptions):
 rows=[r for r in scope['rows'] if r['source']==source];evidence='; '.join(f"{r['id']}: {source}:{r['line']}" for r in rows)
 extra=' Adicionar controle funcional de Relative em 0/1/interior, NaN/infinito e parte absoluta não zero para os dois casters antes da mudança.' if source.endswith('stdlib/foundations/color.rs') else ''
 addition=f'''\n\n## Guards de domínio explícitos — V17, 2026-10-16\n\n### Medição anterior à decisão\n\n{evidence}. Fontes e L0 vigentes lidos antes da prescrição; SHA-256, HEAD `{before['head']}`, working tree não commitado, UTC, status e git diff HEAD --stat em `00_nucleo/diagnosticos/tekt-guards-2026-10-16/before.json.gz`. O inventário anterior, reconfirmado por hash, registra 28 guards em 21 owners; a regra CI pinada manda desdobrar ou mover a condição para o corpo. A medição é estrutura Rust, não prova de defeito funcional ou de melhor leitura por IA. Nenhuma intenção upstream é inferida.\n\n### Responsabilidade exclusiva e aceitação\n\n{decision}{extra}\n\nManutenção interna em fluxo contínuo ADR-0127: sem contrato público, default, compatibilidade ou fase novos. A responsabilidade permanece somente no consumer exclusivo deste L0. Não criar helper apenas para esconder a conjunção, não adicionar supressões nem mudar a configuração do linter. Executar controles funcionais existentes antes do código e preservar seus esperados; o RED real é o gate V17 com 28 avisos, GREEN exige zero V17. Conferir caminhos de sucesso/fallback/erro, curto-circuito e efeitos; resselo restrito por owner. Revalidar build, suíte workspace completa, Clippy all-targets com warnings e expectativas não cumpridas como erro, formato, Rustdoc com warnings como erro, linhagem V1/V5/V15/V26 estrita/reversa e SARIF sem novos avisos. Executar sob 12 GiB, swap zero e um job. Não alegar ganho de memória/desempenho ou paridade global sem medição separada.\n'''
 assert Path(owner).read_text()==before['files'][owner];Path(owner).write_text(before['files'][owner]+addition)
 classified.append(dict(source=source,owner=owner,ids=[r['id'] for r in rows],evidence=evidence,decision=decision+extra,adr0127='internal-continuous'))
(out/'classification.json').write_text(json.dumps(classified,ensure_ascii=False,indent=2)+'\n')
